select id, agent_code, agent_name, description, channel, status, current_published_version_id, created_by, updated_by, created_at, updated_at from agent
and agent_code = #{agentCode}
limit 1

select count(1) from agent
and status = #{status}
and ( agent_code like concat('%', #{keyword}, '%') or agent_name like concat('%', #{keyword}, '%') )

select id, agent_code, agent_name, description, channel, status, current_published_version_id, created_by, updated_by, created_at, updated_at from agent
and status = #{status}
and ( agent_code like concat('%', #{keyword}, '%') or agent_name like concat('%', #{keyword}, '%') )
order by updated_at desc, id asc limit #{pageSize} offset #{offset}
